package OrderProcessing {
    // 数据类型定义
    item def Order {
        attribute orderId: String;
        attribute items: OrderItem[1..*];
        attribute total: Real;
    }

item def OrderItem {
        attribute productId: String;
        attribute quantity: Integer;
    }

item def PaymentInfo {
        attribute method: String;
        attribute amount: Real;
    }

item def ShippingLabel {
        attribute address: String;
        attribute trackingNumber: String;
    }

// 动作定义
    action def ReceiveOrder {
        out item order: Order;
    }

action def ValidateOrder {
        in item order: Order;
        out item validOrder: Order;
        out attribute isValid: Boolean;
    }

action def ProcessPayment {
        in item order: Order;
        in item payment: PaymentInfo;
        out attribute paymentSuccess: Boolean;
    }

---

[07-relationships.md#0] 车辆层次结构
车辆层次结构
```sysml
package VehicleHierarchy {
    // 基础定义
    abstract part def Vehicle {
        attribute mass: Real;
        attribute maxSpeed: Real;
        abstract part powertrain: Powertrain;
    }

abstract part def Powertrain {
        attribute power: Real;
    }

// 特化层次
    part def GroundVehicle :> Vehicle {
        attribute wheelCount: Integer;
    }

part def Car :> GroundVehicle {
        attribute wheelCount :>> GroundVehicle::wheelCount = 4;
        part powertrain :>> Vehicle::powertrain: CarPowertrain;
    }

part def CarPowertrain :> Powertrain {
        part engine: Engine;
        part transmission: Transmission;
    }

// 进一步特化
    part def ElectricCar :> Car {
        part powertrain :>> Car::powertrain: ElectricPowertrain;
    }

part def ElectricPowertrain :> CarPowertrain {
        part engine :>> CarPowertrain::engine: ElectricMotor;
        part battery: Battery;
    }

---

